(1, 'default', NULL, 'About Aire', 'About Us', 'about-us', 'Pioneering next-generation indoor air quality solutions and precision cleanroom filtration systems.', '<p class=\"content-text mt-4\">AIRE is an innovative engineering leader dedicated to high-performance indoor air quality solutions, medical-grade HEPA purification, and commercial air ventilation systems. Founded with a vision to protect human health and enhance indoor environmental well-being, AIRE combines aerosol physics, advanced IoT filtration sensors, and sustainable aerodynamic design.</p><p class=\"content-text mt-3\">From residential living spaces and modern workspaces to critical healthcare laboratories and industrial cleanrooms, AIRE delivers uncompromising air purity, silent efficiency, and intelligent air monitoring worldwide.</p>', 'themes/default/assets/img/Air-Purify.png', 'About Aire | Clean Air Engineering & IAQ Solutions', 'Learn about Aire’s mission to deliver cutting-edge air purification systems, HEPA filtration, and smart clean air technologies.', 'About Aire, indoor air quality, cleanroom technology, HEPA filtration, smart air purifier', 1, 2, 2, '2026-08-26 06:09:49', '2026-10-04 06:24:36'),
(2, 'default', NULL, 'Contact Us', 'Contact Us', 'contact-us', 'At adipisci reprehenderit fugiat ratione quidem illum praesentium enim rerum sed quia.', '<p><span style=\"background-color:rgb(255,255,255);color:rgb(33,37,41);\"><span style=\"-webkit-text-stroke-width:0px;display:inline !important;float:none;font-family:&quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;letter-spacing:normal;orphans:2;text-align:left;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong>Description</strong></span></span></p>', 'https://placehold.co/1200x500?text=Contact+Us', 'Optio repellendus distinctio tenetur quis optio.', 'Ea aliquid et delectus ad molestiae placeat voluptatem iusto impedit est eveniet natus animi neque.', 'blanditiis, et, dolor, maiores, voluptas, dolorem', 1, 1, 1, '2026-08-26 06:09:49', '2026-08-26 06:09:49'),
(3, 'default', NULL, 'Our Heritage & History', 'History', 'history', 'A decade of precision aerosol engineering and groundbreaking air purification milestones.', '<p class=\"content-text mt-4\">AIRE began as a specialized aerosol filtration research lab in 2015, striving to engineer particulate filtration systems capable of capturing sub-micron pathogens without heavy energy draw. Over the past decade, AIRE has deployed thousands of clean air systems across hospitals, cleanrooms, enterprise offices, and modern households around the world.</p>', 'themes/default/assets/img/Air-Purify.png', 'History & Milestones | Aire Indoor Air Quality', 'Explore Aire’s journey from an aerosol research laboratory to an international leader in clean air solutions.', 'Aire history, air purification innovations, clean air engineering milestones', 1, 2, 2, '2026-08-26 06:09:49', '2026-10-04 06:24:36'),
(4, 'default', NULL, 'Sports', 'Sports', 'sports', 'Voluptatem qui saepe repellat officiis dicta autem consequatur et illum est corporis labore tempore accusantium et sapiente.', '', 'https://placehold.co/1200x500?text=Sports', 'Consequuntur explicabo est corrupti id est.', 'Sequi iure qui veritatis maxime velit sit neque animi aut dolore blanditiis nisi et quia cumque autem quos dolorum molestias cupiditate.', 'eaque, ut, sint, distinctio, voluptas, illo', 1, 1, 1, '2026-08-26 06:09:49', '2026-09-29 05:11:12'),
(5, 'legal', 5, 'Cookie Policy', 'Legal & Compliance', 'cookie-policy', 'We believe in complete transparency. Learn how and why AIRE uses cookies to optimize your browsing and shopping experience.', '<h2><span style=\"color:hsl(210,75%,60%);\"><strong>Cookie Policy</strong></span></h2><p><strong>Effective Date:</strong>&nbsp;21 October 2026</p><p><strong>Last Updated:</strong>&nbsp;21 October 2026</p><p>This Cookie Policy explains how AIRE uses cookies and similar technologies on its website.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>1. Introduction</strong></span></h3><p>This Cookie Policy explains how AIRE (“AIRE”, “we”, “us” or “our”) uses cookies and similar technologies when you visit our website, www.aire.bd. It should be read together with our Privacy Policy.</p><p>AIRE is a Bangladesh-based business providing fresh air solutions, ventilation systems, energy recovery ventilation (ERV), heat recovery, air purification, indoor air quality monitoring and related environmental technologies.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>2. What Are Cookies?</strong></span></h3><p>Cookies are small text files that a website may store on your device when you visit it. They help websites operate, remember preferences, understand how visitors use pages and, where enabled, support selected marketing functions.</p><p>Similar technologies may include pixels, tags, local storage and scripts that collect or store information about website use.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>3. Types of Cookies We May Use</strong></span></h3><ul><li data-list-item-id=\"e9fddbd2dcd345612fa4eca0284bfa2ab\"><strong>Strictly necessary cookies:</strong>&nbsp;These support essential website functions, security, navigation, shopping-cart or checkout functions, and services you specifically request. They cannot be switched off through our cookie preference tool where they are essential to the service.</li><li data-list-item-id=\"e197199b347fd51ae7cfc61fbea09cbc4\"><strong>Preference or functional cookies:</strong>&nbsp;These remember choices such as language, region or other settings to make your visit more convenient.</li><li data-list-item-id=\"ee441cea2d00a651d5f172fd1ba2c0066\"><strong>Analytics and performance cookies:</strong>&nbsp;These help us understand website traffic, page performance, visitor interactions and technical issues so we can improve our website.</li><li data-list-item-id=\"e2c22e5f60b4b2205c71ee56f75d10453\"><strong>Marketing cookies:</strong>&nbsp;Where enabled, these may help measure advertising effectiveness or provide content and promotions that are more relevant to your interests.</li></ul><p>The actual cookies used depend on the website features and third-party services currently enabled on www.aire.bd.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>4. Why We Use Cookies</strong></span></h3><ul><li data-list-item-id=\"ee96e14d6ae68aabf170e3d96d7945eae\">To keep the website secure and functioning correctly.</li><li data-list-item-id=\"ef051be5d8f24e736b580ee1c02a49c23\">To remember your preferences and improve usability.</li><li data-list-item-id=\"e4cf35549ea2b9b021238e52ffb62f9ed\">To understand website traffic and improve content, performance and navigation.</li><li data-list-item-id=\"e32752593ea7a59e04601c9b53fc999a4\">To support shopping, enquiry, account or checkout functions where available.</li><li data-list-item-id=\"e9caf008ab913b2cd2cc7c7c8b4a2e856\">To measure marketing performance, but only where such tools are enabled and the required consent has been obtained.</li></ul><h3><span style=\"color:hsl(210,75%,60%);\"><strong>5. Consent and Cookie Preferences</strong></span></h3><p>Where required by applicable law, we will ask for your consent before placing or activating non-essential cookies. Strictly necessary cookies may operate without consent where they are required to provide a service you request or to keep the website secure.</p><p>If a cookie banner or preference tool is available, you can use it to accept all cookies, reject non-essential cookies or choose individual categories. You should be able to revisit your choices through the website’s cookie settings where that feature is provided.</p><p>Withdrawing consent does not affect the lawfulness of any processing carried out before you withdrew it.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>6. Managing Cookies Through Your Browser</strong></span></h3><p>Most browsers allow you to view, block or delete cookies through their settings. If you block all cookies, some website features may not work properly or your preferences may not be remembered.</p><p>Browser instructions differ by device and browser. Check the help section of your browser for the latest steps to manage or delete cookies.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>7. Third-Party Cookies</strong></span></h3><p>Some website functions may be provided by third parties, such as analytics, video, map, social media, payment or marketing service providers. If these services are enabled, they may place or access cookies under their own policies and terms.</p><p>AIRE does not control the independent cookie practices of third parties. We encourage you to review their privacy and cookie notices. Third-party cookies should only be activated in accordance with applicable law and your preferences where consent is required.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>8. Personal Information and Cookies</strong></span></h3><p>Cookie information may sometimes be linked with technical information such as your IP address, browser, device, pages visited or interaction data. We handle personal information in accordance with our Privacy Policy and applicable laws in Bangladesh.</p><p>We do not intend to use non-essential cookies to collect more information than is reasonably needed for the purposes described in this Policy.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>9. Changes to This Cookie Policy</strong></span></h3><p>We may update this Cookie Policy when our website, technologies, service providers or legal requirements change. The latest version will be published on this page with an updated “Last Updated” date. We encourage you to review it periodically.</p><h3><span style=\"color:hsl(210,75%,60%);\"><strong>10. Contact AIRE</strong></span></h3><p>If you have questions about this Cookie Policy or our use of cookies, please contact us:</p><p><strong>AIRE</strong></p><p><strong>Attention:</strong>&nbsp;Privacy and Data Protection Enquiries</p><p><strong>Address:</strong>&nbsp;Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</p><p><strong>Email:</strong> <a href=\"mailto:hasibur.aire@gmail.com\">hasibur.aire@gmail.com</a></p><p><strong>Telephone:</strong>&nbsp;+880 1711 181 790</p><p><strong>Website:</strong> <a href=\"https://www.aire.bd/\">www.aire.bd</a></p>', 'themes/default/assets/img/og-share-banner.jpg', 'Cookie Policy | AIRE Industries', 'Learn how AIRE uses cookies and similar tracking technologies to ensure secure browsing and personalized air quality experiences.', 'Cookie Policy, cookie preferences, GDPR compliance, tracking technologies, AIRE privacy', 1, 2, 2, '2026-10-04 06:24:35', '2026-10-28 05:31:18'),
(6, 'legal', 5, 'Privacy Policy', 'Legal & Compliance', 'privacy-policy', 'Your privacy is paramount. Understand how AIRE collects, processes, encrypts, and protects your personal information.', '<h2>Privacy Policy</h2><p><strong>Effective Date:</strong> 21 October 2026 | <strong>Last Updated:</strong> 21 October 2026</p><h2>1. Introduction</h2><p>AIRE (“we”, “us”, or “our”) respects your privacy and is committed to protecting your personal information when you visit our website, request a quotation, purchase products, or contact us.</p><h2>2. Information We Collect</h2><p>We may collect:</p><ul><li data-list-item-id=\"ef4514a81a7daf0d13dfb9e174966e579\"><strong>Personal &amp; Contact Details:</strong> Name, email, phone number, address, and company information.</li><li data-list-item-id=\"e44eddc7b0c23c3fb6d15b8b4c9d87edb\"><strong>Enquiries &amp; Orders:</strong> Product interests, quotations, purchases, payments, deliveries, and warranty requests.</li><li data-list-item-id=\"ed063dec07a791ff0f58202e57af84e96\"><strong>Project Information:</strong> Building details, floor plans, ventilation requirements, and technical specifications.</li><li data-list-item-id=\"e9709c6ac506566529de5cf3a71b5acb5\"><strong>Technical Data:</strong> IP address, browser, device information, website activity, and security logs.</li><li data-list-item-id=\"e37feed96ce15b8cc7dccc59ed80e143f\"><strong>Preferences:</strong> Account details, marketing choices, and cookie consent records.</li></ul><h2>3. How We Use Your Information</h2><p>We use your information to respond to enquiries, prepare quotations, process orders, arrange deliveries, provide technical and after-sales support, improve our website, prevent fraud, meet legal obligations, and send permitted marketing communications.</p><h2>4. Legal Basis for Processing</h2><p>We process personal information where permitted by applicable law, including to fulfil contracts, comply with legal obligations, pursue legitimate business interests, or obtain your consent where required. You may withdraw consent at any time.</p><h2>5. Payments &amp; Cookies</h2><p>Payments may be handled by third-party payment providers. We do not intend to store complete payment card details on our own systems.</p><p>Our website may use necessary, preference, analytics, and marketing cookies. Non-essential cookies will only be activated with the required consent. You can manage your preferences through our cookie settings.</p><h2>6. Sharing &amp; International Transfers</h2><p><strong>AIRE does not sell your personal information.</strong> We may share relevant data with service providers, payment processors, delivery partners, professional advisers, or authorities where legally required. Where information is transferred internationally, we will apply safeguards required by applicable law.</p><h2>7. Data Retention &amp; Security</h2><p>We retain personal information only as long as reasonably necessary for business, contractual, and legal purposes. We use appropriate security measures to protect it, although no electronic system can be guaranteed completely secure.</p><h2>8. Your Privacy Rights</h2><p>Subject to applicable law, you may request access to, correction or deletion of your information, restrict or object to certain processing, request data portability, withdraw consent, or lodge a complaint with the relevant authority. Contact us to exercise your rights.</p><h2>9. Marketing &amp; Third-Party Websites</h2><p>You can opt out of marketing communications at any time. Essential service messages may still be sent. External websites have their own privacy policies, and AIRE is not responsible for their independent data practices.</p><h2>10. Children\'s Privacy &amp; Automated Decisions</h2><p>Our services are primarily intended for adults and businesses. We do not knowingly collect children\'s information unlawfully. We do not intend to make solely automated decisions with significant effects unless applicable legal requirements are met.</p><h2>11. Project Confidentiality</h2><p>Building plans, technical drawings, and project documents are used for relevant enquiries, quotations, and services. Access is limited where appropriate, and information will not knowingly be disclosed for unrelated purposes without a lawful basis or authorisation, unless required by law.</p><h2>12. Your Responsibilities &amp; Policy Updates</h2><p>Please provide accurate information and protect your account credentials. We may update this Policy when our business, technology, or legal obligations change. Revisions will be published on our website with an updated date.</p><h2>13. Contact Us</h2><p>For privacy questions, data requests, or complaints, contact:</p><p><strong>AIRE — Privacy &amp; Data Protection</strong></p><ul><li data-list-item-id=\"eb423acf33cb6890b4d1dca61520dd6d2\"><strong>Address:</strong> Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</li><li data-list-item-id=\"e39c8771458558e49e3c0ef3c2dd5c15a\"><strong>Email:</strong> <a href=\"mailto:hasibur.aire@gmail.com\">hasibur.aire@gmail.com</a></li><li data-list-item-id=\"e0c4b8bb1106a606757779f648a5a21ed\"><strong>Phone:</strong> <a href=\"tel:+8801711181790\">+880 1711 181 790</a></li><li data-list-item-id=\"e13651044f0717b12a9c3b292c1af7360\"><strong>Website:</strong> <a href=\"https://www.aire.bd/\">www.aire.bd</a></li></ul><p>You may also contact the relevant data protection authority where applicable. Please avoid sending passwords or unnecessary sensitive information in your requests.</p><p><strong>AIRE — Cleaner Air. Brighter Spaces. A Healthier Tomorrow.</strong></p>', 'pages/6/7Ji7fveNKhh0xvg41XBh0m0Hv9XtEjz3DfCsqsc4.png', 'Privacy Policy | AIRE Industries Data Protection', 'Read AIRE Industries Privacy Policy. Learn about our strict data handling, encryption standards, and your statutory privacy rights.', 'Privacy Policy, data protection, GDPR, personal data rights, AIRE security', 1, 2, 2, '2026-10-04 06:24:35', '2026-10-28 18:17:59'),
(7, 'legal', 5, 'Terms of Service', 'Legal & Compliance', 'terms-of-service', 'Review the binding terms and conditions governing the purchase, delivery, and usage of AIRE products and services.', '<p>These Terms of Service constitute a legally binding agreement between you and AIRE Industries regarding your access to our website, purchase of air purification systems and replacement filter kits, and participation in warranty programs.</p><p>By accessing or utilizing any part of the AIRE ecosystem, you agree to be bound by these provisions, including warranty limitations, acceptable usage criteria, and dispute resolution procedures.</p>', 'themes/default/assets/img/og-share-banner.jpg', 'Terms of Service | AIRE Industries Agreement', 'Review AIRE Terms of Service governing product sales, device warranties, delivery terms, and customer rights.', 'Terms of Service, user agreement, purchase terms, AIRE warranty rules', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:31:06'),
(8, 'legal', 5, 'Data Protection & GDPR', 'Legal & Compliance', 'data-protection', 'Comprehensive overview of AIRE’s adherence to global data protection regulations, encryption, and audit standards.', '<h2 style=\"margin-left:0.0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>Data Protection Policy</strong></span></h2><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Effective Date:</strong></span><span style=\"background-color:#f3f6fa;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Last Updated:</strong></span><span style=\"background-color:#f3f6fa;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\">This Data Protection Policy explains how AIRE collects, uses, stores, discloses and protects personal information when you visit our website, contact us, request a quotation, purchase products, register a product, subscribe to updates or otherwise interact with us.</p><p style=\"margin-left:0.0px;\"><span style=\"color:#181f27;\"><strong>Important:</strong></span> This Policy describes AIRE’s intended data-protection practices. Read it together with the Privacy Policy, Cookie Policy, Terms of Service and any applicable purchase or service terms. Any rights provided by applicable law are not limited by this Policy.</p><p style=\"margin-left:0.0px;\"><strong>1. About AIRE and This Policy</strong></p><p style=\"margin-left:0.0px;\">“AIRE”, “we”, “us” and “our” refer to the business operating <a href=\"https://www.aire.bd/\"><span style=\"color:#0d6a9f;\"><u>www.aire.bd</u></span></a>. “You” refers to a visitor, customer, prospective customer, supplier, business contact or other individual whose personal information we process.</p><p style=\"margin-left:0.0px;\">AIRE provides fresh-air solutions, ventilation systems, energy recovery ventilation (ERV), heat recovery, air purification, indoor air quality monitoring and related environmental technologies. This Policy covers information processed through our website and in enquiries, sales, after-sales support, warranty claims, product registration, marketing subscriptions and business communications. Additional notices may apply to specific services or transactions.</p><p style=\"margin-left:0.0px;\"><strong>2. What Is Personal Information?</strong></p><p style=\"margin-left:0.0px;\">Personal information is information that identifies, relates to, describes or could reasonably be linked to an identifiable individual. It may include information you provide directly and technical or usage information collected when you use our website.</p><p style=\"margin-left:0.0px;\"><strong>3. Information We May Collect</strong></p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"ead899ae9039982e788147575c92005a7\"><span style=\"color:#181f27;\"><strong>Identity and contact details:</strong></span> name, job title, company, email, telephone, billing address and delivery address.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ef0082a7ad1f22e487057905a70fe04c2\"><span style=\"color:#181f27;\"><strong>Enquiries and communications:</strong></span> messages, quotation requests, product questions, feedback, support requests and communication records.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eb21f66fa899efbbc822129d3dfcda089\"><span style=\"color:#181f27;\"><strong>Orders and transactions:</strong></span> products purchased or considered, order and delivery details, invoices, payment status, returns, warranty claims and service history. Payment details may be handled by payment providers. AIRE should not store full card security codes.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ecbf9891bccb53304749dc2ee56c413de\"><span style=\"color:#181f27;\"><strong>Account and product information:</strong></span> account identifiers, product model and serial number, registration, installation and support details.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e54b90ca3cff93b3dcf82fe3900a8c7da\"><span style=\"color:#181f27;\"><strong>Technical and usage data:</strong></span> IP address, browser and device details, operating system, approximate location derived from technical data, pages visited, referring pages, timestamps and diagnostic logs.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e8e43a806ef0a49dd4aa89f180427fe5e\"><span style=\"color:#181f27;\"><strong>Cookies and preferences:</strong></span> cookie choices, consent records and analytics information, subject to applicable consent requirements.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e96ddf351ba9a5119509b27c1ff7b2a3d\"><span style=\"color:#181f27;\"><strong>Business relationship information:</strong></span> supplier, distributor, installer and business-contact details and professional interaction records.</li></ul><p style=\"margin-left:0.0px;\">Please do not send sensitive personal information through general enquiry forms unless it is necessary and the form specifically supports it.</p><p style=\"margin-left:0.0px;\"><strong>4. How We Collect Information</strong></p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e9d3d3bc1fcfaa85efab9b4e9743303c1\">Directly from you through forms, orders, quotation requests, subscriptions and communications.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e126a3a121bca8d6f809822427618a9d3\">When you register a product, request technical support or make a warranty claim.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e0b09d9dc0d2cfbd0312689a7201f1faa\">Automatically through website logs, cookies and similar technologies, according to your settings and applicable law.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ec09bdb501a444797d52492af9868b49c\">From service providers involved in payment processing, delivery, hosting, analytics or customer support.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e999097c9617fd01b884c69e5f5d02bb3\">From business partners or publicly available professional sources where appropriate and lawful.</li></ul><p style=\"margin-left:0.0px;\"><strong>5. Why We Use Personal Information</strong></p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e8cb70dc6559256e6f92c9a851d89a7de\"><span style=\"color:#181f27;\"><strong>Respond to requests:</strong></span> answer questions, handle enquiries and prepare quotations.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eb8faa7c3c942693f286b798d471dcc13\"><span style=\"color:#181f27;\"><strong>Provide products and services:</strong></span> process purchases, arrange delivery or installation, manage accounts, returns and support.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e0b8fc0faff06ed18a0a61dbf4ae5f4e0\"><span style=\"color:#181f27;\"><strong>Registration and warranty:</strong></span> verify product details, assess warranty coverage, troubleshoot issues and maintain service records.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e6d4dd436b7ec6ef6aa8fb7a7461c1ad9\"><span style=\"color:#181f27;\"><strong>Operate and improve our website:</strong></span> maintain functionality, diagnose problems and improve content and services.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e3ac39ad90a385d0b8029360ecb4c1509\"><span style=\"color:#181f27;\"><strong>Security and fraud prevention:</strong></span> protect users, systems and transactions and investigate suspected misuse.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eb2e5cab2ab3b486dbadd9a80e4680cd5\"><span style=\"color:#181f27;\"><strong>Business administration:</strong></span> maintain appropriate records and manage supplier and business relationships.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e40c095642340cd03cb96af8cbcf7684c\"><span style=\"color:#181f27;\"><strong>Marketing:</strong></span> send product news or promotional messages where permitted and, where required, with your consent.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e5e3835506edd4c41cc7cdf2da365704f\"><span style=\"color:#181f27;\"><strong>Legal purposes:</strong></span> meet legal obligations, respond to lawful requests and establish, exercise or defend legal claims.</li></ul><p style=\"margin-left:0.0px;\"><strong>6. Legal Grounds for Processing</strong></p><p style=\"margin-left:0.0px;\">Where applicable law requires a legal basis, we will rely on an appropriate basis for the activity, which may include:</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e713cb631223769902210856f10e7e2e5\"><span style=\"color:#181f27;\"><strong>Contract or pre-contract steps:</strong></span> to respond to a request, provide a quotation, fulfil an order or deliver a service.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ee6b6007d9b8bcdad51ae7e0b63b1871b\"><span style=\"color:#181f27;\"><strong>Legal obligation:</strong></span> to maintain records or comply with applicable law.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ef7812ea89525de593cbf1bd067fb5343\"><span style=\"color:#181f27;\"><strong>Consent:</strong></span> for activities such as certain cookies or marketing where consent is required. You may withdraw consent at any time.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e968485d521be9732006c21c1d69fb8ac\"><span style=\"color:#181f27;\"><strong>Legitimate interests:</strong></span> where permitted by law, for website security, service improvement, customer administration and protection of our business, provided those interests do not override applicable rights.</li></ul><p style=\"margin-left:0.0px;\">The legal grounds and rights available may vary depending on your location and the law applicable to the processing.</p><p style=\"margin-left:0.0px;\"><strong>7. Marketing and Your Choices</strong></p><p style=\"margin-left:0.0px;\">Service messages about orders, warranties, safety or support are different from promotional communications. We send promotional messages only where permitted by law and with consent where required. You may unsubscribe using the link in a marketing email or contact us. We may retain limited information on a suppression list to respect your opt-out.</p><p style=\"margin-left:0.0px;\"><strong>8. Cookies and Similar Technologies</strong></p><p style=\"margin-left:0.0px;\">Our website may use strictly necessary, preference, analytics or marketing cookies and similar technologies. Non-essential cookies will be used subject to applicable law and any consent required. Manage available choices through our cookie settings and browser settings. Please read the AIRE Cookie Policy for further information. Blocking some cookies may affect website functionality.</p><p style=\"margin-left:0.0px;\"><strong>9. When We Share Information</strong></p><p style=\"margin-left:0.0px;\">We do not sell personal information as a standalone commercial product. We may share it, where necessary, with:</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"efb8ed8b3c2c0e05c0ad4376c0ede0fc9\"><span style=\"color:#181f27;\"><strong>Service providers:</strong></span> hosting, IT support, security, email delivery, analytics, customer service and data-storage providers.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e90f41dac3281ec3f243788dc2ccd5ea8\"><span style=\"color:#181f27;\"><strong>Payment providers:</strong></span> payment gateways, banks and fraud-prevention providers involved in transactions.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"edb5b36cd24aea7aeb39368f3881db238\"><span style=\"color:#181f27;\"><strong>Delivery and installation partners:</strong></span> couriers, logistics companies, installers, distributors and authorised service centres.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ebcb2e959803d2d12a51574998c9fefd5\"><span style=\"color:#181f27;\"><strong>Professional advisers:</strong></span> lawyers, accountants, auditors and insurers subject to appropriate confidentiality duties.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e65f5a2b290b97517a6fe7683fd2fcbf8\"><span style=\"color:#181f27;\"><strong>Authorities:</strong></span> regulators, courts or law-enforcement bodies where disclosure is required by law or necessary to protect rights, safety or security.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eb5a775e522ad6ce7596aa33fe13d954f\"><span style=\"color:#181f27;\"><strong>Business successors:</strong></span> a prospective or actual buyer or successor in a reorganisation, transfer or sale, subject to appropriate safeguards.</li></ul><p style=\"margin-left:0.0px;\">We expect service providers processing information for us to use it only for authorised purposes and apply appropriate confidentiality and security measures.</p><p style=\"margin-left:0.0px;\"><strong>10. International Data Transfers</strong></p><p style=\"margin-left:0.0px;\">Some service providers or systems may be located outside Bangladesh or your country. Where personal information is transferred internationally, we will take steps required by applicable law to protect it, which may include contractual safeguards, security measures or other lawful transfer mechanisms.</p><p style=\"margin-left:0.0px;\"><strong>11. Data Retention</strong></p><p style=\"margin-left:0.0px;\">We retain personal information only as long as reasonably necessary to provide services, maintain product and warranty records, resolve disputes, enforce agreements and meet legal, accounting or reporting requirements. Retention depends on the type of information, our relationship with you, applicable law and potential claims. When information is no longer required, we will take reasonable steps to delete, anonymise or securely dispose of it, subject to lawful retention obligations.</p><p style=\"margin-left:0.0px;\"><strong>12. Information Security</strong></p><p style=\"margin-left:0.0px;\">We use reasonable organisational, technical and administrative measures designed to protect personal information against accidental loss, unauthorised access, alteration, disclosure or destruction. Measures may include access controls, authentication, secure transmission, system monitoring, backups and limiting access to personnel who need the information for their work.</p><p style=\"margin-left:0.0px;\">No website, network or electronic storage method can be guaranteed completely secure. Keep account credentials confidential and contact us promptly if you suspect a security issue involving your interaction with AIRE.</p><p style=\"margin-left:0.0px;\"><strong>13. Your Rights and Requests</strong></p><p style=\"margin-left:0.0px;\">Depending on applicable law, you may have the right to:</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"ef8de4ee568fb9e883114a5f8bbc46331\">request access to personal information we hold about you;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ea8742d07ea892bea6d5897cf81f0fbfd\">ask us to correct inaccurate or incomplete information;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e47167975acb6b99d18761cd810dd409d\">request deletion where the law permits;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e55bdfd925c10306ac8d32b3b2ecc66cd\">object to or request restriction of certain processing;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e30a581d8032871e66964268f93061237\">withdraw consent where processing is based on consent;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e0240727af14cc3050604a4e02c05e254\">request a portable copy of certain information where that right applies; and</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e804cae85e402ef243938d5c7d51a31dd\">complain to a competent regulator or data-protection authority where available.</li></ul><p style=\"margin-left:0.0px;\">These rights may be subject to exceptions. Contact us using Section 18. We may need to verify your identity or clarify your request and will respond within the period required by applicable law.</p><p style=\"margin-left:0.0px;\"><strong>14. Children’s Information</strong></p><p style=\"margin-left:0.0px;\">Our website and services are intended for business and general audiences and are not knowingly directed at children. We do not knowingly collect children’s personal information for marketing purposes. If you believe a child has provided information to us, contact us so we can review the matter and take appropriate steps where required.</p><p style=\"margin-left:0.0px;\"><strong>15. Third-Party Websites and Services</strong></p><p style=\"margin-left:0.0px;\">Our website may link to third-party websites, platforms or services. They operate under their own privacy notices and terms. AIRE is not responsible for independent third parties’ privacy, security or content practices. Review their notices before providing information.</p><p style=\"margin-left:0.0px;\"><strong>16. Data Breaches and Security Incidents</strong></p><p style=\"margin-left:0.0px;\">If we become aware of a personal-data breach affecting information under our control, we will assess it and take reasonable steps to contain, investigate and remediate the incident. Where applicable law requires notification to individuals, regulators or others, we will make the required notifications.</p><p style=\"margin-left:0.0px;\"><strong>17. Changes to This Policy</strong></p><p style=\"margin-left:0.0px;\">We may update this Policy to reflect changes in our operations, website features, service providers, technologies or legal requirements. The latest version will appear on this page with a revised “Last Updated” date. Please review it periodically.</p><p style=\"margin-left:0.0px;\"><strong>18. Contact AIRE</strong></p><p style=\"margin-left:0.0px;\">For data-protection questions, privacy requests or concerns, contact:</p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;\"><strong>AIRE</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Attention:</strong></span><span style=\"background-color:#f3f6fa;\"> Privacy and Data Protection Enquiries</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Address:</strong></span><span style=\"background-color:#f3f6fa;\"> Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Email:</strong></span><span style=\"background-color:#f3f6fa;color:#28313a;\"> </span><a href=\"mailto:hasibur.aire@gmail.com\"><span style=\"background-color:#f3f6fa;color:#0d6a9f;\"><u>hasibur.aire@gmail.com</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Telephone:</strong></span><span style=\"background-color:#f3f6fa;color:#28313a;\"> </span><a href=\"tel:+8801711181790\"><span style=\"background-color:#f3f6fa;color:#0d6a9f;\"><u>+880 1711 181 790</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Website:</strong></span><span style=\"background-color:#f3f6fa;color:#28313a;\"> </span><a href=\"https://www.aire.bd/\"><span style=\"background-color:#f3f6fa;color:#0d6a9f;\"><u>www.aire.bd</u></span></a></p><p style=\"margin-left:0.0px;\">This document is a general policy template, not legal advice. Before publication, confirm that it accurately reflects AIRE’s actual data collection, systems, vendors and retention practices, and have it reviewed by a qualified legal professional for applicable legal requirements.</p><p><br>&nbsp;</p>', 'themes/default/assets/img/og-share-banner.jpg', 'Data Protection & GDPR Compliance | AIRE', 'Explore AIRE’s global data protection protocols, AES-256 encryption, and GDPR compliance framework.', 'Data Protection, GDPR compliance, data privacy, AES-256 encryption, DPO contact', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:31:02'),
(9, 'legal', 5, 'Modern Slavery Statement', 'Legal & Compliance', 'modern-slavery-statement', 'Our steadfast pledge to eradicate modern slavery, human trafficking, and unethical labor from our supply chain.', '<h2 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>Modern Slavery Statement</strong></span></h2><p style=\"margin-left:0px;\"><strong>Effective Date:</strong> 21 October 2026</p><p style=\"margin-left:0px;\"><strong>Last Updated:</strong> 21 October 2026</p><p style=\"margin-left:0px;\"><strong>Our commitment</strong></p><p style=\"margin-left:0px;\">AIRE does not tolerate modern slavery, forced labour, human trafficking or the unlawful exploitation of children. We are committed to responsible business practices and to addressing these risks in our operations and supply chains.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>1. Our Commitment</strong></span></h3><p style=\"margin-left:0px;\">AIRE is committed to conducting its business ethically, responsibly and with respect for human rights. We do not tolerate modern slavery, forced labour, human trafficking, debt bondage or the unlawful exploitation of children in our business or supply chains.</p><p style=\"margin-left:0px;\">This Modern Slavery Statement explains the principles and practical steps AIRE uses to identify, prevent and address these risks. It applies to our business activities and informs our expectations of suppliers, contractors, agents and other business partners.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>2. About AIRE</strong></span></h3><p style=\"margin-left:0px;\">AIRE is a Bangladesh-based business working with fresh-air solutions, ventilation systems, air purification, indoor air quality monitoring and related environmental technologies. Our operations may involve suppliers and service providers in Bangladesh and other markets.</p><p style=\"margin-left:0px;\">We recognise that risks can arise at different points in a supply chain, including manufacturing, raw-material sourcing, logistics, labour recruitment, cleaning, maintenance and other contracted services.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>3. What We Mean by Modern Slavery</strong></span></h3><p style=\"margin-left:0px;\">Modern slavery is an umbrella term for severe forms of exploitation in which a person cannot refuse or leave work freely. It can include:</p><ul style=\"margin-left:0px;\"><li style=\"margin-left:0px;\" data-list-item-id=\"e85cf253e7b3c2c574b990c166bcb4df8\">Forced, bonded or compulsory labour.</li><li style=\"margin-left:0px;\" data-list-item-id=\"ede5bda7f2b527cfb47fbea3cb7535ce8\">Human trafficking and exploitation through threats, coercion, deception or abuse of vulnerability.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e0b51ad48d7684f12f0ee631bf7bace71\">Debt bondage, including recruitment-related debt that restricts a worker’s freedom.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e5b0b25bd8038eff7bd646218411a241c\">Unlawful or exploitative child labour.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e0ff8fea75c9e23c4933693bbdbee51bf\">Withholding identity documents, wages or freedom of movement to control a worker.</li></ul><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>4. Our Standards and Expectations</strong></span></h3><p style=\"margin-left:0px;\">AIRE expects people working for or with us to be treated with dignity and fairness. We expect suppliers and business partners to:</p><ul style=\"margin-left:0px;\"><li style=\"margin-left:0px;\" data-list-item-id=\"eee1f295c9b1fc38a76a040c4073aaf83\">Comply with applicable labour, employment, health and safety, and human-rights laws.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e88cb9a82bf4de228251b3390d8886dab\">Employ workers voluntarily and allow them to leave employment in accordance with applicable law and contract terms.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e37b53f5d48abcdc9f434ea6071c09e0b\">Never use threats, violence, intimidation, deception, or restrictions on movement to control workers.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e83aa1bad0bf8049647a50ddc56fbc3c1\">Not charge workers unlawful recruitment fees or require them to surrender passports, identity documents or wages as a condition of work.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e89ab5a4030830eff1687413901deccfd\">Verify that workers meet applicable minimum-age requirements and protect young workers from hazardous or prohibited work.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e6cb306c64a73b1db52596547805fb7e3\">Provide lawful wages, clear employment terms, reasonable working hours, and safe working conditions.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e35a61a737d0d2d28562368ccfd9f7449\">Communicate these standards to their own suppliers and recruitment intermediaries.</li></ul><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>5. Risk Assessment and Due Diligence</strong></span></h3><p style=\"margin-left:0px;\">AIRE aims to take a proportionate, risk-based approach to identifying and addressing modern-slavery risks. Depending on the nature and scale of a supplier relationship, this may include:</p><ul style=\"margin-left:0px;\"><li style=\"margin-left:0px;\" data-list-item-id=\"e420bc6b0f15136a0f9bbc2485a491a08\">Considering the country, sector, product and service involved, and the use of labour-intensive or subcontracted work.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e8b66d162402b047fef5eef0ad5ec902f\">Requesting information about labour practices, recruitment arrangements and relevant policies.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e8ad5a3593b6e2cef7c16934d1f09678c\">Conducting reasonable checks before appointing suppliers and when material risks or concerns arise.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e2b93214404219f87d7ad23d2abee0994\">Seeking clarification or corrective action where information indicates a potential risk.</li><li style=\"margin-left:0px;\" data-list-item-id=\"e9413d9161967cefe21647c256256559a\">Reviewing supplier relationships if concerns remain unresolved.</li></ul><p style=\"margin-left:0px;\">These measures are intended to support responsible decisions. They do not guarantee that every risk can be identified or eliminated.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>6. Supplier Selection and Monitoring</strong></span></h3><p style=\"margin-left:0px;\">AIRE seeks to work with suppliers and partners who share our commitment to lawful and ethical conduct. Where appropriate, we may communicate our expectations in purchasing terms, supplier communications or contractual requirements.</p><p style=\"margin-left:0px;\">If credible concerns are identified, AIRE may request information, agree a corrective-action plan, suspend new orders or reconsider the business relationship. Decisions will take account of the seriousness of the concern, worker safety and the feasibility of effective remediation.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>7. Reporting Concerns</strong></span></h3><p style=\"margin-left:0px;\">Workers, suppliers, customers and other stakeholders are encouraged to raise concerns about possible modern slavery, forced labour, trafficking or labour exploitation. Reports should provide as much relevant detail as can safely be shared.</p><p style=\"margin-left:0px;\">Concerns can be sent to AIRE using the contact details in Section 10. AIRE will review reports in good faith and, where appropriate, seek further information or take action. We aim to treat reports sensitively and discourage retaliation against anyone who raises a concern honestly.</p><p style=\"margin-left:0px;\">If there is an immediate danger to a person, contact the appropriate local emergency or law-enforcement service.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>8. Training and Awareness</strong></span></h3><p style=\"margin-left:0px;\">AIRE aims to improve awareness of modern-slavery risks among relevant staff and decision-makers in a manner proportionate to our activities. This may include guidance on warning signs, supplier questions, responsible escalation and the handling of concerns.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>9. Governance, Review and Continuous Improvement</strong></span></h3><p style=\"margin-left:0px;\">AIRE’s management is responsible for overseeing this statement and considering material concerns raised about our operations or supply chains. We intend to review this statement periodically and update our approach as our business, supply-chain relationships and understanding of risk develop.</p><p style=\"margin-left:0px;\">This statement describes AIRE’s current approach and commitments. It should not be read as a claim that every supply-chain risk has already been independently audited or eliminated.</p><h3 style=\"margin-left:0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>10. Contact AIRE</strong></span></h3><p style=\"margin-left:0px;\">For questions or to report a concern relating to this statement, contact:</p><p style=\"margin-left:0px;\"><strong>AIRE</strong></p><p style=\"margin-left:0px;\"><strong>Attention:</strong>Modern Slavery and Responsible Business Enquiries</p><p style=\"margin-left:0px;\"><strong>Address:</strong>Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</p><p style=\"margin-left:0px;\"><strong>Email:</strong> <a href=\"mailto:hasibur.aire@gmail.com\"><u>hasibur.aire@gmail.com</u></a></p><p style=\"margin-left:0px;\"><strong>Telephone:</strong> <a href=\"tel:+8801711181790\"><u>+880 1711 181 790</u></a></p><p style=\"margin-left:0px;\"><strong>Website:</strong> <a href=\"https://www.aire.bd/\"><u>www.aire.bd</u></a></p>', 'themes/default/assets/img/og-share-banner.jpg', 'Modern Slavery Statement | Ethical Supply Chain AIRE', 'Read AIRE’s annual Modern Slavery Statement detailing supply chain transparency and fair labor standards.', 'Modern Slavery Statement, ethical supply chain, corporate social responsibility, fair labor', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:30:57');
INSERT INTO `pages` (`id`, `temp`, `menu_id`, `page_title`, `breadcrumb`, `slug`, `short_des`, `page_description`, `f_image`, `meta_title`, `meta_description`, `meta_keyword`, `status`, `createdBy`, `updatedBy`, `created_at`, `updated_at`) VALUES
(10, 'legal', 5, 'Export Compliance', 'Legal & Compliance', 'export-compliance', 'International trade adherence, customs regulations, and export governance for commercial cleanroom systems.', '<h2 style=\"margin-left:0.0px;\"><span style=\"color:hsl(210,75%,60%);\"><strong>Export Compliance Policy</strong></span></h2><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Effective Date:</strong></span><span style=\"background-color:#f3f6fa;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Last Updated:</strong></span><span style=\"background-color:#f3f6fa;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\">AIRE is committed to conducting cross-border business responsibly and in accordance with applicable export, customs, trade-control, sanctions and product-compliance requirements. This Policy outlines the principles AIRE expects to follow when exporting, supplying, transferring or facilitating the movement of products, components, software, technical information or related services across borders.</p><p style=\"margin-left:0.0px;\"><span style=\"color:#181f27;\"><strong>Important notice:</strong></span> Export requirements depend on the product, its technical characteristics, origin, destination, end user, intended end use and route. This page provides general compliance information; it is not a guarantee that a particular product or transaction may be exported, and it is not legal advice. AIRE will assess applicable requirements for each transaction where relevant.</p><p style=\"margin-left:0.0px;\"><strong>1. Scope</strong></p><p style=\"margin-left:0.0px;\">This Policy applies to AIRE’s employees, representatives and relevant business partners involved in international sales, order processing, procurement, shipping, distribution, installation, technical support or the transfer of technical information. It covers, as applicable, air ventilation equipment, energy recovery ventilation (ERV) systems, heat recovery products, air purification equipment, indoor air quality monitors, spare parts, accessories, software and technical documentation.</p><p style=\"margin-left:0.0px;\">Specific product lines or transactions may be subject to additional requirements, licences, permits, certifications or customer terms. Where this Policy conflicts with applicable law, the law prevails.</p><p style=\"margin-left:0.0px;\"><strong>2. Compliance with Applicable Laws</strong></p><p style=\"margin-left:0.0px;\">AIRE aims to comply with the export-control, customs, sanctions, import, product-safety, labelling, tax, foreign-exchange and trade-documentation rules that apply to a transaction. Depending on the circumstances, relevant requirements may arise in Bangladesh, the destination country, transit countries, or countries connected with the goods, technology, parties or payment route.</p><p style=\"margin-left:0.0px;\">Before shipment or transfer, AIRE may need to confirm whether an export is permitted, whether a registration, declaration, licence or authorisation is required, and whether destination-country import requirements have been met. Requirements can change; the applicable rules in force at the time of the transaction must be checked.</p><p style=\"margin-left:0.0px;\"><strong>3. Product Classification and Export Authorisations</strong></p><p style=\"margin-left:0.0px;\">Products may need to be classified using the applicable customs tariff or Harmonized System (HS) code. Certain goods, software or technical information may also be subject to strategic-goods or dual-use controls depending on their specifications and intended use.</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e7274a8dec589c7746cca9f0da7fc8d4e\">AIRE will seek to use accurate product descriptions and tariff classifications in export documents.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e9f147fb06dd226b9ea08598b9caf65e8\">Where required, AIRE or the responsible exporter will seek the necessary export licence, permit, registration, certificate or other official authorisation before shipment.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e9f239c62382954a867a505ee72ed4ba8\">Technical specifications, product configurations and accessories may affect classification or authorisation requirements.</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e37618bb541fdb28dabb585460e9bd9a4\">No statement on this website should be interpreted as confirmation that every AIRE product is unrestricted or exempt from licensing.</li></ul><p style=\"margin-left:0.0px;\"><strong>4. Sanctions and Restricted-Party Screening</strong></p><p style=\"margin-left:0.0px;\">Where relevant to the transaction, AIRE may screen customers, distributors, agents, freight forwarders, banks, end users and other parties against applicable sanctions or restricted-party lists. Screening may consider ownership or control, country restrictions and other legal factors where required.</p><p style=\"margin-left:0.0px;\">AIRE may pause, refuse, cancel or place a transaction on hold while a potential match or compliance concern is reviewed. A transaction will not proceed where doing so would violate applicable sanctions or other binding restrictions. A name match alone does not necessarily establish a violation and may require further review.</p><p style=\"margin-left:0.0px;\"><strong>5. End-Use and End-User Checks</strong></p><p style=\"margin-left:0.0px;\">Depending on the product, destination and risk indicators, AIRE may request information about the buyer, final consignee, installation location and intended end use. Customers and partners must provide complete and accurate information and promptly notify AIRE if the end user, destination or intended use changes.</p><p style=\"margin-left:0.0px;\">AIRE may decline or suspend a transaction where there are reasonable grounds to suspect unlawful diversion, prohibited use, evasion of export controls, or a material misrepresentation. Additional documentation may be requested before an order is accepted or released for shipment.</p><p style=\"margin-left:0.0px;\"><strong>6. Prohibited Conduct and Diversion</strong></p><p style=\"margin-left:0.0px;\">Customers, distributors and other partners must not knowingly use AIRE products or services to breach applicable law or facilitate prohibited transactions. They must not:</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e1adf23c88278638f38c99c570e4fc09c\">misstate the product, value, origin, destination, consignee or end user in trade documents;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ef13229899315064388226e91dec5362b\">route goods through another country or intermediary to evade applicable controls or sanctions;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ec06a759e5ae1120df9550dcf45c474f6\">resell, transfer or divert products in breach of applicable export restrictions or licence conditions;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e4823249e467ef2f9ccc00db3ad32a80a\">provide false, misleading or incomplete information in response to compliance enquiries; or</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e9f90d9cc1f71b0b8f65eb86793554e30\">request that AIRE omit, falsify or improperly alter invoices, shipping documents, declarations or certificates.</li></ul><p style=\"margin-left:0.0px;\"><strong>7. Customs Declarations and Trade Documentation</strong></p><p style=\"margin-left:0.0px;\">Export shipments must be supported by accurate and complete documentation appropriate to the transaction and applicable requirements. Depending on the shipment, documents may include:</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e9c68d06344bd2d8748d9bb97117dee9a\">purchase order, sales contract, export letter of credit or other accepted payment/contract documentation;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e4430bbb2e6f7c6d9175f6f0ae93fec12\">commercial invoice and packing list;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eca6803656dfb55c1d8d369b8df71c608\">export declaration or Bill of Export/Shipping Bill;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e1393b3ab0e52fcc8fbb033f2ff95b7ea\">applicable export registration, tax/VAT or business registration documentation;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eb2c704ff2ac36c2dd94e43669dfebf34\">certificate of origin, where required or requested;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eea5a10161e0ab334e884925f1be7a230\">transport documents, such as a bill of lading, airway bill or road consignment note;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e4763c1105108ea63002ca136d2eb4903\">product-specific permits, conformity documents, inspection reports or quality certificates, where required; and</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eea62a74adf79c159f64ec8b8fcf35766\">any other supporting documents required by the relevant customs authority, bank, carrier or destination country.</li></ul><p style=\"margin-left:0.0px;\">The documents required vary by product, transaction structure, shipping route and destination. AIRE will not represent that a document is legally required for every shipment unless that requirement has been verified for the relevant case.</p><p style=\"margin-left:0.0px;\"><strong>8. Product Standards, Safety and Destination Requirements</strong></p><p style=\"margin-left:0.0px;\">Products may be subject to destination-specific requirements relating to electrical safety, electromagnetic compatibility, energy efficiency, radio equipment, environmental rules, labelling, language, packaging, waste or recycling obligations, and conformity assessment. The applicable requirements depend on the product and market.</p><p style=\"margin-left:0.0px;\">Customers and importers are responsible for confirming their local import and installation obligations, except to the extent AIRE has expressly agreed in writing to provide specific compliance documentation or assume a defined responsibility. Product certificates or test reports must not be altered, misrepresented or used for products outside their stated scope.</p><p style=\"margin-left:0.0px;\"><strong>9. Country of Origin and Preferential Trade Claims</strong></p><p style=\"margin-left:0.0px;\">Any country-of-origin statement or preferential tariff claim must be supported by appropriate evidence and comply with the rules applicable to the relevant destination and trade arrangement. A product’s shipping location, seller address or brand origin does not by itself determine its legal country of origin.</p><p style=\"margin-left:0.0px;\">AIRE will provide origin-related information or supporting documents only where it has a reasonable basis to do so. Customers must not change or reproduce origin declarations in a misleading way.</p><p style=\"margin-left:0.0px;\"><strong>10. Shipping, Freight Forwarders and Delivery Partners</strong></p><p style=\"margin-left:0.0px;\">AIRE may use carriers, freight forwarders, customs brokers, distributors or other logistics partners to arrange international shipments. These parties must receive accurate shipment information and be given any documentation needed to perform their agreed role.</p><p style=\"margin-left:0.0px;\">Shipment timing may be affected by customs inspections, licensing checks, incomplete documents, carrier restrictions, sanctions reviews, port conditions or other events outside AIRE’s reasonable control. AIRE may delay dispatch while a compliance issue is investigated or until required approvals are obtained.</p><p style=\"margin-left:0.0px;\"><strong>11. Payment, Banking and Trade-Finance Controls</strong></p><p style=\"margin-left:0.0px;\">International payments and trade-finance arrangements may be subject to bank checks, foreign-exchange rules, anti-fraud requirements and other applicable restrictions. AIRE may request reasonable information to verify a payer, payment route or transaction purpose and may pause a transaction if a bank or competent authority requires further review.</p><p style=\"margin-left:0.0px;\">Customers must not request false invoices, artificial price changes, misleading payment descriptions or payment arrangements intended to conceal the parties or purpose of a transaction.</p><p style=\"margin-left:0.0px;\"><strong>12. Records and Audits</strong></p><p style=\"margin-left:0.0px;\">AIRE aims to maintain appropriate records of export transactions, classifications, screening decisions, licences, declarations and supporting documents for the periods required by applicable law and internal recordkeeping procedures. Access to such records should be limited to authorised personnel and service providers with a legitimate need.</p><p style=\"margin-left:0.0px;\">Where appropriate, AIRE may review transaction records, request supporting information from partners or investigate a compliance concern. Records will be handled in accordance with applicable privacy and data-protection requirements.</p><p style=\"margin-left:0.0px;\"><strong>13. Responsibilities of Customers and Business Partners</strong></p><p style=\"margin-left:0.0px;\">Customers, importers, distributors, agents and other partners are expected to:</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"eff04b660f3f65cc9234f5a93dcedd6b1\">provide accurate details about their identity, business, destination, consignee and intended end use;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e929c920466b07aeca4be51860eca5e68\">obtain import licences, local registrations and permits that are their responsibility;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ed4821face9b708e4a569a27f822940c0\">comply with applicable export, import, sanctions, customs and product laws;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e338c23465f27b6305b77898d14b33ce6\">preserve relevant transaction and product records where required;</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ef87a9e853dd636257f4d65c85b104011\">notify AIRE of changes that may affect the legality or accuracy of a shipment; and</li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e59e75655dd060d5fffa0b21170ad59ff\">cooperate reasonably with legitimate compliance checks.</li></ul><p style=\"margin-left:0.0px;\"><strong>14. Reporting a Concern</strong></p><p style=\"margin-left:0.0px;\">If you believe a transaction, request or shipment may breach this Policy or applicable trade requirements, please contact AIRE promptly. Provide enough information to help us identify the relevant order or activity. AIRE will review concerns in a proportionate manner and may request further details.</p><p style=\"margin-left:0.0px;\">Please do not send passwords, full payment-card details or unrelated sensitive personal information when reporting a concern.</p><p style=\"margin-left:0.0px;\"><strong>15. Holds, Refusal and Cancellation</strong></p><p style=\"margin-left:0.0px;\">To protect compliance and manage risk, AIRE may request further documents, delay fulfilment, suspend access to a transaction, refuse an order or cancel a transaction where it reasonably considers that a legal requirement, licence condition, sanctions restriction or material compliance concern may apply. Where legally and practically appropriate, AIRE may explain the reason for the action or identify information needed to continue the review.</p><p style=\"margin-left:0.0px;\">This section does not override any mandatory consumer rights, contractual obligations or remedies that cannot lawfully be excluded.</p><p style=\"margin-left:0.0px;\"><strong>16. Policy Updates</strong></p><p style=\"margin-left:0.0px;\">AIRE may update this Policy to reflect changes in products, business operations, supply chains or applicable requirements. The revised version will be published on this page with an updated “Last Updated” date. The version applicable to a particular transaction may also be affected by the law and authorisations in force at the relevant time.</p><p style=\"margin-left:0.0px;\"><strong>17. Contact AIRE</strong></p><p style=\"margin-left:0.0px;\">For export-compliance questions, documentation requests or concerns, contact:</p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;\"><strong>AIRE</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Attention:</strong></span><span style=\"background-color:#f3f6fa;\"> Export Compliance / Commercial Enquiries</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Address:</strong></span><span style=\"background-color:#f3f6fa;\"> Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Email:</strong></span><span style=\"background-color:#f3f6fa;color:#28313a;\"> </span><a href=\"mailto:hasibur.aire@gmail.com\"><span style=\"background-color:#f3f6fa;color:#0d6a9f;\"><u>hasibur.aire@gmail.com</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Telephone:</strong></span><span style=\"background-color:#f3f6fa;color:#28313a;\"> </span><a href=\"tel:+8801711181790\"><span style=\"background-color:#f3f6fa;color:#0d6a9f;\"><u>+880 1711 181 790</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#f3f6fa;color:#181f27;\"><strong>Website:</strong></span><span style=\"background-color:#f3f6fa;color:#28313a;\"> </span><a href=\"https://www.aire.bd/\"><span style=\"background-color:#f3f6fa;color:#0d6a9f;\"><u>www.aire.bd</u></span></a></p><p style=\"margin-left:0.0px;\"><strong>18. Official Information Resources</strong></p><p style=\"margin-left:0.0px;\">The following official resources may help users identify relevant Bangladesh export and customs requirements. They are provided for general reference; the applicable rules and current official guidance should be checked for each transaction.</p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"ec6b76e5a64daf03de80da218b914a922\"><a href=\"https://mincom.gov.bd/pages/policies/export-policy-2024-2027-english-version-f6bfc2-69403139c4774958d7b41ce2\"><u>Bangladesh Ministry of Commerce — Export Policy 2024–2027 (English version)</u></a></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e58815738e57d320bea848d0ea093fe42\"><a href=\"https://bangladeshcustoms.gov.bd/trade_info/customs_clearance\"><u>Bangladesh Customs — Customs Clearance and export procedures</u></a></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eee56dc5d23e3544946450dec48006768\"><a href=\"https://ccie.gov.bd/pages/policies\"><u>Office of the Chief Controller of Imports and Exports (CCI&amp;E) — Policies and notices</u></a></li></ul><p style=\"margin-left:0.0px;\">This page is a general compliance-policy template and is not legal advice. Before publication, AIRE should confirm that it accurately reflects its products, export destinations, actual screening procedures and contractual arrangements. Have the final policy reviewed by qualified trade-compliance counsel and update it when applicable laws or official guidance change.</p><p><br>&nbsp;</p>', 'themes/default/assets/img/og-share-banner.jpg', 'Export Compliance & Trade Governance | AIRE', 'Understand AIRE’s international trade adherence and export controls for cleanroom air filtration systems.', 'Export Compliance, trade regulations, customs compliance, cleanroom export', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:30:53'),
(11, 'legal', 5, 'Legal Notice', 'Legal & Compliance', 'legal-notice', 'Corporate registration, intellectual property notices, and legal disclaimers for AIRE Industries.', '<h2 style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:hsl(210,75%,60%);\"><strong>Legal Notice</strong></span></h2><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Important information about this website, its content, intellectual property, product information and the terms under which the website may be used.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:#28374b;\"><strong>Effective date:</strong></span><span style=\"background-color:#ffffff;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:#28374b;\"><strong>Last updated:</strong></span><span style=\"background-color:#ffffff;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\"><strong>Please read this notice carefully.</strong> By accessing or using <a href=\"https://www.aire.bd/\"><span style=\"color:#103b6d;\"><u>www.aire.bd</u></span></a> and its associated pages, you agree to use the website lawfully and in accordance with the notices and policies published on it.</p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>1. Website operator and contact details</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">This website is operated under the AIRE name. For legal correspondence, intellectual-property concerns or questions about the website, please contact us using the details below.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;\"><strong>AIRE — Legal and Compliance Enquiries</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;\">Attention: Legal Notice</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;\">Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;color:#1d2735;\">Email: </span><a href=\"mailto:hasibur.aire@gmail.com\"><span style=\"background-color:#fafcff;color:#103b6d;\"><u>hasibur.aire@gmail.com</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;color:#1d2735;\">Telephone: </span><a href=\"tel:+8801711181790\"><span style=\"background-color:#fafcff;color:#103b6d;\"><u>+880 1711 181 790</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;color:#1d2735;\">Website: </span><a href=\"https://www.aire.bd/\"><span style=\"background-color:#fafcff;color:#103b6d;\"><u>www.aire.bd</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">The exact registered legal name, registration number and other statutory particulars should be stated here where applicable and verified before publication.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>2. Website content and purpose</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">This website provides information about AIRE, its products, technologies, air-quality and ventilation solutions, services, resources and related business activities. Content is provided for general informational and commercial purposes. We aim to keep it clear and current, but do not guarantee that every page is complete, error-free or up to date at all times.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>3. Intellectual property</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Unless otherwise stated, website text, graphics, photographs, illustrations, layouts, icons, videos, downloads, product descriptions, and original design or technical materials are owned by AIRE or used with permission and may be protected by copyright, trademark, design, patent or other intellectual-property laws.</span></p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e29318c6f7c3d73bc80970dacc3d1f4e7\"><span style=\"background-color:#ffffff;\">You may view and print reasonable portions for personal, non-commercial reference.</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ea710dd950090cb972c407d616953504d\"><span style=\"background-color:#ffffff;\">You must not reproduce, republish, modify, distribute, sell, publicly display or commercially exploit protected material without prior written permission, except where applicable law permits it.</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e97644e5218f14b0ee49f29e099c93f03\"><span style=\"background-color:#ffffff;\">You must not remove copyright notices, ownership statements or other rights-management information.</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e23dc12bbd4c2536ed3af0c39cb5892fe\"><span style=\"background-color:#ffffff;\">Nothing on this website grants you a licence to use AIRE’s name, logos, marks, designs or other intellectual property unless expressly stated in writing.</span></li></ul><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>4. Trademarks and third-party materials</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">AIRE names, logos and product or service identifiers may be trademarks or other protected marks of their respective owners. Third-party company names, product names, logos and marks appearing on this website belong to their respective owners and are used for identification or informational purposes only. Their appearance does not necessarily imply endorsement, partnership or affiliation.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>5. Product information, specifications and availability</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Product images, dimensions, performance figures, specifications, compatibility details, prices, delivery estimates and availability are provided as general guidance and may change. Images may differ from the final product, and product configurations can vary by model, market or order.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Always check the current product documentation, quotation, order confirmation and applicable installation instructions before making a purchase or relying on a specification. Where a written contract, warranty or mandatory consumer law provides otherwise, that document or law takes precedence.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>6. Technical and environmental information</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Information concerning air quality, filtration, ventilation, indoor environments, energy performance or technical applications is general information, not a substitute for a project-specific assessment by a suitably qualified professional. Actual results depend on factors such as building conditions, installation, maintenance, usage, measurement methods and the surrounding environment.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Do not rely on website content alone to make safety-critical, medical, engineering or regulatory decisions. Obtain appropriate professional advice and follow product manuals and applicable standards.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>7. Acceptable use</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You must not misuse this website, attempt unauthorised access, interfere with its operation, introduce malicious code, scrape or harvest information in breach of applicable law, misrepresent your identity, or use the website in a way that infringes the rights of AIRE or others. We may take proportionate steps to protect the website, users and our rights where misuse is reasonably suspected.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>8. External links and third-party services</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">This website may link to third-party websites, platforms, documents or services for convenience. We do not control and are not responsible for their content, availability, security or privacy practices. A link does not by itself constitute an endorsement. Please review the terms and privacy notices of any third-party service you use.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>9. Website availability and security</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">We may update, suspend, restrict or discontinue parts of the website for maintenance, security, operational or business reasons. Although reasonable measures may be taken to protect the website, no internet service or electronic transmission can be guaranteed to be completely secure or uninterrupted.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>10. Disclaimer and limitation of liability</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">To the maximum extent permitted by applicable law, the website and its general content are provided on an “as available” basis without warranties that cannot lawfully be excluded. AIRE does not exclude or limit liability where doing so would be unlawful, including any non-excludable rights or liabilities under applicable consumer-protection law.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Subject to those legal limits, AIRE is not responsible for loss arising solely from reliance on general website information that has not been confirmed for the relevant product, project or transaction, or from the use of third-party websites outside our control. Nothing in this notice overrides an express written warranty or contract that applies to a purchase.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>11. Privacy and cookies</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Our handling of personal information and use of cookies or similar technologies is explained in our </span><a href=\"https://v2.aire.bd/pages/privacy-policy\"><span style=\"background-color:#ffffff;color:#103b6d;\"><u>Privacy Policy</u></span></a><span style=\"background-color:#ffffff;\"> and </span><a href=\"https://v2.aire.bd/pages/cookie-policy\"><span style=\"background-color:#ffffff;color:#103b6d;\"><u>Cookie Policy</u></span></a><span style=\"background-color:#ffffff;\">. Please consult those documents for details about data practices and available choices.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>12. Legal notices and intellectual-property complaints</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">If you believe that material on this website infringes your legal rights, please email us with the page URL, a description of the material and concern, your contact details, and any information reasonably needed to assess the matter. Please identify the right you believe has been infringed and provide evidence of your authority to act, where relevant.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Sending a message to this email address does not necessarily constitute valid service of a formal legal notice where a particular method or address is required by law or contract. Use any legally required service method and address.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>13. Governing law</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">This notice and use of the website are intended to be interpreted in accordance with the laws of Bangladesh, subject to any mandatory laws or consumer rights that apply in the circumstances. Any dispute will be dealt with by a court or other competent forum with jurisdiction under applicable law.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>14. Updates to this notice</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">We may revise this notice when our website, business, products or legal obligations change. The updated version will be published on this page with a revised “Last updated” date. Please review it periodically.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>15. Contact</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">For questions about this Legal Notice, contact:</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>AIRE — Legal and Compliance Enquiries</strong></span><br><span style=\"background-color:#ffffff;\">Email: </span><a href=\"mailto:hasibur.aire@gmail.com\"><span style=\"background-color:#ffffff;color:#103b6d;\"><u>hasibur.aire@gmail.com</u></span></a><br><span style=\"background-color:#ffffff;\">Telephone: </span><a href=\"tel:+8801711181790\"><span style=\"background-color:#ffffff;color:#103b6d;\"><u>+880 1711 181 790</u></span></a><br><span style=\"background-color:#ffffff;\">Address: Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</span></p><p style=\"margin-left:0.0px;\">© 2026 AIRE. All rights reserved. This notice is part of the website’s Policies &amp; Legal information.</p><p><br>&nbsp;</p>', 'themes/default/assets/img/og-share-banner.jpg', 'Legal Notice & Intellectual Property | AIRE', 'Official corporate identity, patent disclosures, and legal notices for AIRE Industries.', 'Legal Notice, corporate registration, patents, trademarks, AIRE disclaimer', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:30:46');
INSERT INTO `pages` (`id`, `temp`, `menu_id`, `page_title`, `breadcrumb`, `slug`, `short_des`, `page_description`, `f_image`, `meta_title`, `meta_description`, `meta_keyword`, `status`, `createdBy`, `updatedBy`, `created_at`, `updated_at`) VALUES
(12, 'legal', 5, 'Website Terms of Use', 'Legal & Compliance', 'terms-of-use', 'Acceptable usage guidelines, intellectual property rules, and digital security standards for AIRE platforms.', '<h2 style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:hsl(210,75%,60%);\"><strong>Website Terms of Use</strong></span></h2><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Acceptable usage guidelines, intellectual property rules and digital security standards for AIRE’s website and online platforms.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:#28374b;\"><strong>Status:</strong></span><span style=\"background-color:#ffffff;\"> Website terms</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:#28374b;\"><strong>Effective date:</strong></span><span style=\"background-color:#ffffff;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;color:#28374b;\"><strong>Last updated:</strong></span><span style=\"background-color:#ffffff;\"> 22 October 2026</span></p><p style=\"margin-left:0.0px;\"><strong>Important:</strong> By browsing, registering for an account or otherwise using the AIRE website, you agree to follow these Terms of Use. If you do not agree, please stop using the Website. Separate terms may apply to purchases, products, warranties or specific services.</p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>1. Scope and acceptance</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">These Terms of Use (“Terms”) govern access to and use of AIRE’s website, online platforms, product pages, search and discovery tools, account features, downloads and related digital content (“Website”). “AIRE”, “we”, “us” and “our” refer to the operator of the Website under the AIRE name. “You” means a visitor, registered user or organisation using the Website.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">These Terms should be read alongside our Privacy Policy, Cookie Policy, Legal Notice and any terms shown for a particular product, service or transaction. Where a separate written agreement or mandatory law conflicts with these Terms, that agreement or law prevails to the extent of the conflict.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>2. Eligibility and authority</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You must be legally capable of accepting these Terms. If you use the Website for a company or other organisation, you confirm that you are authorised to act on its behalf and bind it to these Terms. If you are not authorised, you must not accept these Terms on that organisation’s behalf.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>3. Account registration and security</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Some Website features may require an account. When registering, provide accurate and current information and update it when it changes. You are responsible for keeping your login credentials confidential and for taking reasonable steps to prevent unauthorised account access.</span></p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"e41ce8ef275049a68e5c03a33dbe68df7\"><span style=\"background-color:#ffffff;\">Do not share your password or allow another person to misuse your account.</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e2b6b7c3fe09c6adce0d7493b035141ec\"><span style=\"background-color:#ffffff;\">Do not create accounts using false identities or information you are not authorised to use.</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e78592bfba183fcc546d55b141bac896e\"><span style=\"background-color:#ffffff;\">Notify AIRE promptly if you suspect unauthorised access or a security incident.</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e1901037fb1045c1578924c6047782afb\"><span style=\"background-color:#ffffff;\">We may request reasonable verification information to protect accounts and services.</span></li></ul><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">We may suspend access where reasonably necessary to protect the Website, users or account holders, subject to applicable law.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>4. Acceptable use</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You may use the Website only for lawful purposes and in a manner consistent with its intended function. You must not:</span></p><ul><li style=\"margin-left:0.0px;\" data-list-item-id=\"ec23827c696978a23139c6847dbaf5d32\"><span style=\"background-color:#ffffff;\">violate applicable laws, regulations, court orders or the rights of another person;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ef5627d90a982a2db8dd0620caa4211bb\"><span style=\"background-color:#ffffff;\">attempt to gain unauthorised access to servers, databases, accounts, networks or administrative systems;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"eaceed70d2c310e4fffcc03508d0462de\"><span style=\"background-color:#ffffff;\">probe, scan or test the vulnerability of any system without prior written authorisation;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e93de3ce6fb1f407a527073de85ac5667\"><span style=\"background-color:#ffffff;\">upload or transmit malware, viruses, malicious scripts or other harmful code;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e26a3f3428ccdf3db2b790d94e57fd65f\"><span style=\"background-color:#ffffff;\">interfere with Website availability, infrastructure, payment gateways, checkout processes or other users’ access;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e68fc29a4577e1281b9982a9f550ec8cb\"><span style=\"background-color:#ffffff;\">use automated scraping, crawling, harvesting or bulk extraction to collect Website content or data, except where authorised by AIRE or permitted by applicable law;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e08938acd665638f0ddc2fb2f76ed15d2\"><span style=\"background-color:#ffffff;\">circumvent access controls, rate limits, authentication or other security measures;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e49ce2028ed511aeb27290a6e73ca3670\"><span style=\"background-color:#ffffff;\">impersonate a person or organisation, submit fraudulent information or misrepresent your affiliation;</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"e13168d50ee4cdf2cf590a495fb2f4e5b\"><span style=\"background-color:#ffffff;\">send spam, conduct fraud, distribute unlawful content or use the Website to harass or harm others; or</span></li><li style=\"margin-left:0.0px;\" data-list-item-id=\"ed53af6e5924578bccc123b9a30d5349b\"><span style=\"background-color:#ffffff;\">use Website content or services in a way that infringes intellectual-property, privacy or other legal rights.</span></li></ul><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>5. Digital security and responsible reporting</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You must not attempt to disrupt, damage or compromise the Website or its connected systems. If you identify a potential vulnerability, suspicious activity or security incident, avoid accessing or changing data beyond what is necessary to identify the issue and report it to AIRE through the contact details below. Do not publicly disclose exploitable details before allowing reasonable time for assessment and remediation.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Nothing in this section prohibits activity expressly authorised by AIRE or protected by applicable law.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>6. Intellectual property</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Unless otherwise stated, Website content—including text, graphics, photographs, illustrations, videos, icons, software, page layouts, product information, downloads and original technical materials—is owned by AIRE or used under licence and may be protected by copyright, trademark, design, patent or other laws.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You may view and print reasonable portions for personal or internal reference. Unless we give written permission or applicable law allows it, you must not copy, modify, republish, distribute, sell, publicly display or commercially exploit protected content. Do not remove copyright or ownership notices, and do not suggest that AIRE endorses your product, service or organisation without permission.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>7. Trademarks and third-party materials</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">AIRE names, logos, product names and service identifiers may be trademarks or other protected marks. Third-party names, logos and marks belong to their respective owners. Their appearance on the Website does not necessarily imply endorsement, sponsorship, partnership or affiliation.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Any third-party materials remain subject to their owners’ rights and applicable licence terms.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>8. Product information and transactions</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Product descriptions, images, specifications, dimensions, performance data, compatibility details, prices, availability and delivery estimates are provided for general guidance and may change. We aim to keep information accurate, but do not guarantee that every detail is complete or current at all times.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">A product listing or displayed price is not necessarily a binding offer. Orders are subject to the applicable checkout process, confirmation, quotation or separate agreement. Purchases, payment, delivery, returns, refunds and warranties may be governed by additional terms and policies. Nothing in these Terms limits any right that cannot lawfully be excluded.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>9. Technical and environmental information</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Information about air quality, ventilation, filtration, HVAC systems, building environments, energy performance or other technical applications is general information and is not a substitute for project-specific design, professional assessment, installation instructions or applicable standards. Actual performance depends on building conditions, product configuration, installation, maintenance, usage and environmental factors.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Verify relevant product documentation and consult a suitably qualified professional before relying on information for safety-critical, regulated or engineering decisions.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>10. User submissions and feedback</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">If you submit an enquiry, review, feedback, file or other material, you confirm that you are entitled to provide it and that doing so does not violate law or another person’s rights. Do not submit confidential, sensitive or personal information unless it is necessary and the relevant channel is appropriate.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You grant AIRE permission to use feedback you voluntarily provide to improve our Website and services, without limiting any rights you retain in other submitted material. We will handle personal information in accordance with our Privacy Policy and applicable law. We may moderate, decline or remove submissions where reasonably necessary.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>11. External links and third-party services</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">The Website may link to external websites, payment providers, embedded services or third-party resources. Links are provided for convenience and do not by themselves constitute endorsement. AIRE does not control third-party content, availability, security or privacy practices. Your use of third-party services may be subject to separate terms and policies.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>12. Availability, maintenance and changes</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">We may update, suspend, restrict or discontinue any part of the Website for maintenance, security, operational or business reasons. We do not guarantee uninterrupted access, compatibility with every device or browser, or that the Website will always be error-free. We may change Website content and features over time.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>13. Suspension and termination</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">We may restrict or suspend access if we reasonably believe that these Terms have been breached, the Website is at risk, unlawful activity has occurred or action is needed to protect users or systems. Where reasonable and appropriate, we may provide notice or an opportunity to resolve the issue. You may stop using the Website at any time.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Where account deletion is available, you may use the provided process or contact us for assistance. Certain records may need to be retained for legal, security or legitimate business purposes as explained in our Privacy Policy.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>14. Disclaimer</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">The Website and its general content are provided on an “as available” basis. To the maximum extent permitted by applicable law, AIRE disclaims warranties that may lawfully be excluded. We do not guarantee that Website content will be uninterrupted, error-free or suitable for every purpose.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Nothing in these Terms excludes or limits liability for fraud, wilful misconduct, death or personal injury caused by negligence, non-excludable statutory rights, or any other liability that cannot legally be excluded or limited.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>15. Limitation of liability</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">To the extent permitted by applicable law, AIRE is not liable for indirect or consequential loss arising from use of, or inability to use, the Website, including loss of profits, business opportunity, goodwill or data, where such loss is not otherwise recoverable by law. This clause does not override a separate written contract, express product warranty or mandatory legal protection.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">You are responsible for verifying important product, technical and commercial information before relying on it and for keeping appropriate copies of information you submit.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>16. Indemnity</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">To the extent permitted by law, you are responsible for claims or losses arising from your unlawful use of the Website, your material breach of these Terms or your infringement of another person’s rights. This clause does not apply to the extent a claim or loss results from AIRE’s own conduct or where imposing such responsibility would be unlawful.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>17. Privacy and cookies</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">Our collection and use of personal information and cookies or similar technologies are explained in our </span><a href=\"https://v2.aire.bd/pages/privacy-policy\"><span style=\"background-color:#ffffff;color:#103b6d;\"><u>Privacy Policy</u></span></a><span style=\"background-color:#ffffff;\"> and </span><a href=\"https://v2.aire.bd/pages/cookie-policy\"><span style=\"background-color:#ffffff;color:#103b6d;\"><u>Cookie Policy</u></span></a><span style=\"background-color:#ffffff;\">. Any consent required by law will be requested separately where applicable.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>18. Governing law and disputes</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">These Terms are intended to be governed by the laws of Bangladesh, subject to any mandatory laws or consumer protections that apply to a particular user or transaction. Disputes will be handled by a court or other competent forum with jurisdiction under applicable law. Nothing in these Terms removes rights that cannot lawfully be waived.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>19. Changes to these Terms</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">We may update these Terms to reflect changes to the Website, our services or legal requirements. The latest version will be published on this page with a revised “Last updated” date. Please review the Terms periodically. Where required by law, we will provide notice of material changes.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>20. Severability and no waiver</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">If a provision is held invalid or unenforceable, the remaining provisions will continue to apply to the extent permitted by law. A delay or failure to enforce a provision does not automatically waive the right to enforce it later.</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\"><strong>21. Contact</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#ffffff;\">For questions about these Terms, account access or suspected misuse of the Website, contact AIRE:</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;\"><strong>AIRE — Website and Compliance Enquiries</strong></span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;color:#1d2735;\">Email: </span><a href=\"mailto:hasibur.aire@gmail.com\"><span style=\"background-color:#fafcff;color:#103b6d;\"><u>hasibur.aire@gmail.com</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;color:#1d2735;\">Telephone: </span><a href=\"tel:+8801711181790\"><span style=\"background-color:#fafcff;color:#103b6d;\"><u>+880 1711 181 790</u></span></a></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;\">Address: Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh</span></p><p style=\"margin-left:0.0px;\"><span style=\"background-color:#fafcff;color:#1d2735;\">Website: </span><a href=\"https://www.aire.bd/\"><span style=\"background-color:#fafcff;color:#103b6d;\"><u>www.aire.bd</u></span></a></p><p style=\"margin-left:0.0px;\">© 2026 AIRE. All rights reserved. This document forms part of AIRE’s Policies &amp; Legal information.</p><p><br>&nbsp;</p><p>&nbsp;</p>', 'themes/default/assets/img/og-share-banner.jpg', 'Website Terms of Use | AIRE Platforms', 'Guidelines for acceptable usage, copyright compliance, and digital security on AIRE web platforms.', 'Terms of Use, website rules, acceptable use, platform security', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:30:40'),
(13, 'legal', 5, 'Sitemap & Legal Index', 'Legal & Compliance', 'sitemap', 'Complete directory of AIRE product categories, information pages, and compliance documentation.', '<p>Welcome to the AIRE Sitemap &amp; Legal Index. Explore our complete directory of air purifier categories, ductless split units, cleanroom systems, technical documentation, and compliance documentation.</p>', 'themes/default/assets/img/og-share-banner.jpg', 'Sitemap & Legal Index | AIRE Industries', 'Navigate all AIRE product categories, editorial articles, and legal documents from a single directory.', 'Sitemap, website index, AIRE directory, legal index', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-28 05:30:08'),
(14, 'default', NULL, 'Filtration Technology', 'Technology', 'technology', 'Discover our proprietary multi-stage H13 HEPA, activated carbon, and UV-C purification architectures.', '<p class=\"content-text mt-4\">AIRE systems incorporate multi-layer medical-grade H13 HEPA media, high-density activated carbon pellets for VOC absorption, and photocatalytic UV-C sterilization chambers designed to eliminate 99.97% of airborne pathogens down to 0.1 microns.</p>', 'themes/default/assets/img/Air-Purify.png', 'Filtration Technology & Innovation | Aire', 'Discover Aire’s cutting-edge H13 HEPA filtration and smart indoor air quality sensing technologies.', 'HEPA technology, air purifier filtration, VOC reduction, clean air engineering', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-04 06:24:36'),
(15, 'default', NULL, 'Warranty & Service Policy', 'Support & Services', 'warranty-policy', 'Comprehensive manufacturer warranty, guaranteed part replacements, and certified service plans.', '<p class=\"content-text mt-4\">Every AIRE residential and commercial purifier is backed by our comprehensive manufacturer warranty. We cover all motor assemblies, smart sensor arrays, and circuit components against defects in materials and craftsmanship for up to 5 years.</p><p class=\"content-text mt-3\">Register your device online within 30 days of purchase to activate complimentary priority filter replacement reminders and extended coverage.</p>', 'themes/default/assets/img/Air-Purify.png', 'Warranty & Service Policy | AIRE Air Purifiers', 'Learn about AIRE 5-year warranty coverage, genuine filter guarantees, and certified maintenance support.', 'AIRE warranty, purifier warranty, parts replacement, air purifier service', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-04 06:24:36'),
(16, 'default', NULL, 'Shipping & Delivery Guidelines', 'Customer Service', 'shipping-policy', 'Fast, insured nationwide shipping and white-glove commercial delivery for all purification systems.', '<p class=\"content-text mt-4\">We ensure rapid, temperature-controlled, and insured shipping across all 50 states and international territories. Residential purifier units ship within 24 to 48 business hours with real-time tracking.</p><p class=\"content-text mt-3\">Commercial modular filtration units include freight tracking and scheduled curbside or indoor placement delivery.</p>', 'themes/default/assets/img/Air-Purify.png', 'Shipping & Delivery Guidelines | AIRE', 'Read AIRE shipping timeframes, tracking options, international delivery, and insured freight details.', 'AIRE shipping, delivery policy, air purifier shipping, order tracking', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-04 06:24:36'),
(17, 'default', NULL, 'Returns & Refund Policy', 'Customer Service', 'returns-refunds', '30-day clean air satisfaction guarantee with hassle-free returns and prompt refunds.', '<p>We stand behind the superior performance of AIRE systems with our 30-Day Clean Air Trial. If you are not completely satisfied with your indoor air quality improvement, you may return the unit in its original packaging for a full refund.</p>', 'themes/default/assets/img/Air-Purify.png', 'Returns & Refund Policy | AIRE 30-Day Clean Air Trial', 'Discover AIRE 30-day return policy and simple step-by-step clean air refund process.', 'AIRE returns, refund policy, clean air trial, air purifier return', 1, 2, 2, '2026-10-04 06:24:36', '2026-10-05 01:11:11'),
(18, 'legal', 2, 'Talk to an expert', 'Talk to an expert', 'talk-to-an-expert', 'Get expert advice on air purification, fresh air, ventilation, product selection, and project requirements. Contact AIRE for tailored solutions and technical guidance.', '<h2>Talk to an Expert</h2><p><strong>Find the Right Air Solution for Your Space.</strong></p><p>Get expert guidance on air purification, fresh air, ventilation, and indoor air quality for your home, office, or commercial project.</p><h3>How We Can Help</h3><ul><li data-list-item-id=\"e1cd1bfa8ce298f737bc31f4ee27228fa\"><strong>Air Quality:</strong> Dust, PM2.5, and filtration solutions.</li><li data-list-item-id=\"e12b56720437af242cbc084f622d3b1cf\"><strong>Fresh Air &amp; Ventilation:</strong> System selection and heat recovery.</li><li data-list-item-id=\"e12e3f8436669c69fea3fe4f29d39a013\"><strong>Product &amp; Technical Advice:</strong> Specifications, airflow, and compatibility.</li><li data-list-item-id=\"e26e39ad7d2118f182f8875951a712379\"><strong>Projects &amp; Business:</strong> Building solutions, quotations, and technical support.</li><li data-list-item-id=\"e3f0b02b728776706ce8d9936ba1b19dd\"><strong>After-Sales:</strong> Installation, maintenance, and troubleshooting, subject to availability.</li></ul><h3>Contact Our Team</h3><ul><li data-list-item-id=\"eaecd85ef5da8b0c60e356ff19e6af504\"><strong>Contact Person:</strong> MD Hasibur Rahman, CEO</li><li data-list-item-id=\"ed062b98ba932486dfea479f929843255\"><strong>Phone:</strong> <a href=\"tel:+8801711181790\">+880 1711 181 790</a></li><li data-list-item-id=\"e220019b7e6eab988ae0dd521f6c5460f\"><strong>Email:</strong> <a href=\"mailto:hasibur.aire@gmail.com\">hasibur.aire@gmail.com</a></li><li data-list-item-id=\"e65ac1d9fced0391a7bd48937981fd7a1\"><strong>Website:</strong> <a href=\"https://www.aire.bd/\">www.aire.bd</a></li><li data-list-item-id=\"e81c2a7eef186b781f8f26476ebbdd8a5\"><strong>Office Address:</strong> Unit 105, 154 Motijheel C/A, Dhaka 1000, Bangladesh.</li><li data-list-item-id=\"edb95c917cbbf75151e5bc657978336ff\"><strong>Google Maps:</strong> <a href=\"https://www.google.com/maps/search/?api=1&amp;query=Unit%20105%2C%20154%20Motijheel%20C%2FA%2C%20Dhaka%201000%2C%20Bangladesh\">View Office Location &amp; Get Directions</a></li></ul><h3>Request an Expert Consultation</h3><p>Share your contact details, building type, and requirements. You may also include the product model, project details, or floor plans.</p><p>&nbsp;</p><h3>In Summary</h3><p>Get expert advice on air purification, fresh air, ventilation, product selection, and project requirements. Contact AIRE for tailored solutions and technical guidance.</p><p><strong>AIRE — Cleaner Air. Brighter Spaces. A Healthier Tomorrow.</strong></p><p><br>&nbsp;</p>', 'pages/18/r4sjm6Ed7pJrTGUEokYax2NKz5zN3tXdRJqWu24B.png', NULL, NULL, NULL, 1, 2, 2, '2026-10-21 05:40:36', '2026-10-28 18:10:58'),
(19, 'default', NULL, 'Accessibility', 'Accessibility', 'accessibility', 'Accessibility', '<ul style=\"margin-left:0px;\"><li data-list-item-id=\"e443a6b04096b8d034a3716118c9afc3c\"><a href=\"https://v2.aire.bd/docs\">AccessibilityAccessibilityAccessibilityAccessibility</a></li></ul>', NULL, NULL, NULL, NULL, 1, 1, 1, '2026-10-28 00:55:39', '2026-10-28 00:55:39'),
