(34, 'legal', 2, 'Request a Quote', 'Request a Quote', 'request-a-quote', 'Request a Quote for tailored air purification and ventilation solutions to suit your space, project requirements, and budget.', '<h2><span style=\"color:hsl(210, 75%, 60%);\"><strong>Request a Quote</strong></span></h2><p>Get a tailored quotation for air purifiers, fresh air systems, and ventilation solutions suited to your space, project, and budget.</p><h3>What We Offer</h3><ul><li data-list-item-id=\"e3ba1470e7d966c8eeba9bec3c641abfe\"><strong>Air Purifiers:</strong> Home, office, and indoor spaces.</li><li data-list-item-id=\"e572340754db8378f5e8fbf37d126a795\"><strong>Fresh Air &amp; Ventilation:</strong> Fresh air supply, heat recovery, and ventilation systems.</li><li data-list-item-id=\"ee1e0c10ab634d91727201caf5a1f3900\"><strong>Building &amp; Commercial Projects:</strong> Residential, office, school, hotel, and commercial solutions.</li><li data-list-item-id=\"e4c5adc36e3bb9f0442384a2e42be182b\"><strong>Project &amp; Bulk Orders:</strong> Custom requirements, quantities, and business quotations.</li><li data-list-item-id=\"ed23cfc2cac3d29d8cd4447d86083bd26\"><strong>Replacement &amp; Upgrades:</strong> Compatible products for existing systems.</li></ul><h3>How It Works</h3><ol><li data-list-item-id=\"e88868906616909eba9127787242378b2\"><strong>Share Your Requirements</strong> — Tell us what you need.</li><li data-list-item-id=\"e79b172b4e0fdb646cb932b3295221e8b\"><strong>Enquiry Review</strong> — Our team reviews your details.</li><li data-list-item-id=\"e89cba2cb45778a3aa182ca846e0a9130\"><strong>Receive a Quote</strong> — Get relevant product information and pricing.</li><li data-list-item-id=\"ed5bda5f82c1383e339ce9e01992f69e2\"><strong>Discuss Next Steps</strong> — Clarify specifications and available options.</li></ol><h3>Request Your Quote</h3><p><strong>Contact Information:</strong> Full Name, Company (optional), Email, Phone / WhatsApp, Country / City.</p><p><strong>Product &amp; Project Details:</strong> Product Category, Model (if known), Building Type, Room / Project Area (optional), Quantity, Project Location, Project Stage (optional), Delivery Timeline (optional).</p><p><strong>Additional Information:</strong> Describe your requirements and optionally upload floor plans, BOQ, or technical documents.</p><p><strong>CTA: Request My Quote</strong></p><p><br>&nbsp;</p>', 'pages/34/vNHyffAsbu2dHSs04cj7X4kb4KXBTY7x77SzBHpk.png', NULL, NULL, NULL, 1, 1, 1, '2026-10-28 06:23:29', '2026-10-28 17:57:42'),
(35, 'legal', 2, 'Sales Representative', 'Sales Representative', 'sales-representative', 'Connect with AIRE\'s sales team for product recommendations, pricing, quotations, bulk orders, and project-specific air purification and ventilation solutions.', '<h2>Sales Representative</h2><p>Connect with the AIRE sales team to explore the right air purification and ventilation solutions for your needs. Whether you are purchasing for your home, business, or a large-scale project, our team is here to assist you.</p><h3>How Our Sales Team Can Help</h3><ul><li data-list-item-id=\"eef6c7d6c8e47404dc89b11f9fb2fc21d\"><strong>Product Selection:</strong> Identify suitable products based on your requirements.</li><li data-list-item-id=\"ef49d8a75ce877b2b02fd51129c83514b\"><strong>Pricing &amp; Quotations:</strong> Get product pricing, quotations, and bulk order information.</li><li data-list-item-id=\"edb39fb363e15f1afc458b96ff4d75fcb\"><strong>Project Support:</strong> Discuss requirements for residential, commercial, and institutional projects.</li><li data-list-item-id=\"e3368ecd2a985626179ca1543ba6ef895\"><strong>Technical Coordination:</strong> Connect with our team for product specifications and technical queries.</li><li data-list-item-id=\"e99d49c1b28f9c278896cb3f4397a0f30\"><strong>Business Enquiries:</strong> Explore opportunities for dealers, distributors, contractors, and corporate buyers.</li></ul><h3>Contact Our Sales Team</h3><ul><li data-list-item-id=\"e83edd4441080174e5665a8ba3cf1f961\"><strong>Phone:</strong> [Official Sales Phone Number]</li><li data-list-item-id=\"ed59cecbf6acbc5fa06c51dc970d2813c\"><strong>Email:</strong> [Official Sales Email]</li><li data-list-item-id=\"e88895589c551ae29ba2b1127b50b4a16\"><strong>WhatsApp:</strong> [Official WhatsApp Number]</li><li data-list-item-id=\"ee7ab8683896425b0075b9ddf9c274f67\"><strong>Business Hours:</strong> [Confirmed Business Hours]</li></ul><p><strong>CTA:</strong> Contact a Sales Representative</p>', 'pages/35/iwbF8Hf67eXXsNlvZakT9AyImf23Tpg9WqNM5JVA.webp', NULL, NULL, NULL, 1, 1, 1, '2026-10-28 06:23:52', '2026-10-28 17:48:17'),
(36, 'legal', 2, 'Partner With Us', 'Partner With Us', 'partner-with-us', 'Partner with AIRE to explore dealer, distribution, project, and business collaboration opportunities in air purification and ventilation solutions.', '<h2><span style=\"color:hsl(210,75%,60%);\"><strong>Partner With Us</strong></span></h2><p>Join AIRE\'s growing network of partners and explore opportunities to deliver advanced air purification and fresh air solutions to homes, businesses, and commercial projects.</p><h3>Partnership Opportunities</h3><ul><li data-list-item-id=\"e0d1d4313451e06215b8ac0873a8083a0\"><strong>Dealers &amp; Distributors:</strong> Partner with us to distribute AIRE products in your market.</li><li data-list-item-id=\"e1168bb57e6814b71ad3b8fb8dc5f2982\"><strong>Architects &amp; Consultants:</strong> Integrate suitable air solutions into your designs and projects.</li><li data-list-item-id=\"e5db53d87dec6fbdb16f9ada151e59f91\"><strong>Developers &amp; Contractors:</strong> Collaborate on residential, commercial, and institutional projects.</li><li data-list-item-id=\"e34c54d482bb46c08a981aaf69c093736\"><strong>Corporate Partners:</strong> Explore bulk purchasing and business collaboration opportunities.</li><li data-list-item-id=\"efddd065ef4b983edbcac5c53ee839c92\"><strong>Resellers &amp; Business Partners:</strong> Discuss potential sales and distribution partnerships.</li></ul><h3>Why Partner With AIRE?</h3><ul><li data-list-item-id=\"e44d38eb4afa2fdb1f0964804b574879d\">Innovative air purification and ventilation solutions.</li><li data-list-item-id=\"e060ce76eb89364625aeaba86fc7cd12c\">Product information and technical guidance.</li><li data-list-item-id=\"eefbddcfee6057efe282de1bca8a6407e\">Project-based product selection and quotation support.</li><li data-list-item-id=\"e545fed64ad2bccefb8880f3e636240c5\">Opportunities to develop long-term business relationships.</li></ul><h3>Become a Partner</h3><p>Interested in working with AIRE? Share your company profile, business location, areas of interest, and partnership goals. Our team will review your enquiry and contact you to discuss suitable opportunities.</p><ul><li data-list-item-id=\"e9c6e9f2ec55f2adc977cd1b49ca4a18b\"><strong>Email:</strong> [Official Partnership Email]</li><li data-list-item-id=\"e73d2a5e5f50d541eb0fab87cf7bdd8ed\"><strong>Phone:</strong> [Official Business Phone Number]</li><li data-list-item-id=\"e2b99b199666c59b482bf74ffab71c413\"><strong>Business Hours:</strong> [Confirmed Business Hours]</li></ul>', 'pages/36/LaVNFJSYkt17BMuVjMjWZtANaVIL1ffxzf6heHd9.webp', NULL, NULL, NULL, 1, 1, 1, '2026-10-28 06:24:06', '2026-10-28 17:52:56'),
(37, 'legal', 2, 'Media Inquiries', 'Media Inquiries', 'media-inquiries', 'Contact AIRE for press enquiries, interviews, company and product information, approved media assets, and media collaboration opportunities.', '<h2><span style=\"color:hsl(210, 75%, 60%);\"><strong>Media Inquiries</strong></span></h2><p>For media professionals, journalists, publishers, and content creators seeking information about AIRE, our products, or indoor air quality, please contact our team.</p><h3>How We Can Help</h3><ul><li data-list-item-id=\"eeb3ff756d8118f6ab67d1c73acf4cec1\"><strong>Press &amp; Media:</strong> Company information, official statements, and media requests.</li><li data-list-item-id=\"e3adb0f147d9b16d697d3d427286e0ffc\"><strong>Product Information:</strong> Details about AIRE\'s air purification and ventilation solutions.</li><li data-list-item-id=\"e262a62d4739d1f32bdba2c9012270e17\"><strong>Interviews &amp; Expert Comments:</strong> Requests for interviews and expert insights, subject to availability.</li><li data-list-item-id=\"e53fb23ddd90abd62b5ebde3a455a29a5\"><strong>Brand Assets:</strong> Approved logos, product images, and company materials.</li><li data-list-item-id=\"e6d4ce9c6d5cdaa374c67d46bad71cb1e\"><strong>News &amp; Collaborations:</strong> Media partnerships, features, and editorial opportunities.</li></ul><h3>Contact Our Media Team</h3><p>Please include your name, organisation, publication or media platform, deadline, and details of your enquiry.</p><ul><li data-list-item-id=\"e9572834fe6313a1b069e62a94834bd25\"><strong>Email:</strong> [Official Media Email]</li><li data-list-item-id=\"e36c2d8fcf9cea39a23d37d9fcfca6559\"><strong>Phone:</strong> [Official Media Contact Number]</li><li data-list-item-id=\"e8e114e63f18acfbe5dbc72d5e7c40655\"><strong>Response Time:</strong> [Confirmed Response Time]</li></ul><p><strong>CTA:</strong> Contact the Media Team</p>', 'pages/37/dQaLymaOcTJ9u5qae1wAmN5o3mQnJ7U7lvxHI8qH.webp', NULL, NULL, NULL, 1, 1, 1, '2026-10-28 06:24:18', '2026-10-28 17:54:36'),
(38, 'legal', 2, 'Office Locations', 'Office Locations', 'office-locations', 'Find AIRE\'s office location, contact details, business hours, and directions. Connect with our team for product enquiries, consultations, quotations, partnerships, and customer support.', '<h2><span style=\"color:hsl(210, 75%, 60%);\"><strong>Office Locations</strong></span></h2><ul><li data-list-item-id=\"e26edc585694f866dfb143368631a491c\"><h2>Find Us. Connect With Us.</h2></li><li data-list-item-id=\"e02ca08b3b55c6e8ff9f25be2cf90d340\">Visit or contact AIRE for product enquiries, expert consultations, business partnerships, and project support. Find our office location and connect with the right team for your needs.</li><li data-list-item-id=\"ee8a917c6009511f9f76ab6a0159e099f\"><h3>Our Office</h3></li><li class=\"ck-list-marker-bold\" data-list-item-id=\"e36f45f9084cc8100c9d96dee5d8c9440\"><strong>AIRE — Bangladesh Office</strong></li><li data-list-item-id=\"e9cff5a71bbdda4d0d7bcacb6560cf805\"><strong>Address:</strong> [Full Office Address, City, Bangladesh]</li><li data-list-item-id=\"ec0f79cb01c3f6a3d407118dac1b02e97\"><strong>Phone:</strong> [Official Contact Number]</li><li data-list-item-id=\"e8bb157fb17aa388becc5f22daaeef4dd\"><strong>Email:</strong> [Official Email Address]</li><li data-list-item-id=\"ee70037ede45037abfc5857e568560342\"><strong>Office Hours:</strong> [Confirmed Business Hours]</li><li data-list-item-id=\"e7a5d6eaba15bb8c9d0982da849a1080b\"><strong>Location:</strong> [Google Maps Link]</li><li class=\"ck-list-marker-bold\" data-list-item-id=\"e0a6b86111a72d4181c221a529d8705d2\"><strong>CTA: Get Directions</strong></li><li data-list-item-id=\"eece88ce1417f3079a7f9d3d59b6597e5\"><h3>How We Can Help</h3></li><li data-list-item-id=\"e42eafb066d4153d2a8793ee4bc143784\"><strong>Product Enquiries:</strong> Air purifiers, fresh air, and ventilation solutions.</li><li data-list-item-id=\"edd92587fbed5ea4507ac05e39ddebce4\"><strong>Expert Consultation:</strong> Product selection and technical guidance.</li><li data-list-item-id=\"eca84ba0a8c5229d847a1e53391a5314f\"><strong>Sales &amp; Quotations:</strong> Pricing, bulk orders, and project requirements.</li><li data-list-item-id=\"e260cccd0c0ce9b8153fd75d44c910fac\"><strong>Business Partnerships:</strong> Dealer, distributor, and corporate enquiries.</li><li data-list-item-id=\"eb7bfe3388b2570f39c32bbdf11147d03\"><strong>Customer Support:</strong> Product information and after-sales assistance.</li><li data-list-item-id=\"eabd4e37e1673850a670b217e4692f957\"><h3>Plan Your Visit</h3></li><li data-list-item-id=\"e003781075e669f5a95864e86c4658198\"><p>For product discussions, technical consultations, or project meetings, we recommend scheduling an appointment in advance to ensure the appropriate team member is available.</p><p>&nbsp;</p></li></ul>', 'pages/38/xZWV1NVxjYs7kgTcDg6ivaXkprLWtAn5N0PRlCTe.webp', NULL, NULL, NULL, 1, 1, 1, '2026-10-28 06:24:38', '2026-10-28 18:01:51');

